package main

import (
	"bytes"
	"fmt"
	"go/format"
	"go/token"
	"go/types"
	pathpkg "path"
	"path/filepath"
	"slices"
	"text/template"
)

// Names the generated file declares in its package. To keep a hand-written
// Options next to it, generate into a separate package.
const (
	// funcName is the generated function.
	funcName = "Options"
	// receiversType is the struct the generated function takes its method
	// receivers in. A struct, not one parameter per receiver, so that adding
	// a receiver type never changes the function's signature.
	receiversType = "Receivers"
)

// emit renders the generated Go file.
func emit(s *spec, target *types.Package, rs []resolved) ([]byte, error) {
	for _, name := range []string{funcName, receiversType} {
		if target.Scope().Lookup(name) != nil {
			return nil, fmt.Errorf("package %s already declares %s; generate into a separate package", target.Name(), name)
		}
	}
	m, err := newFileModel(s, target, rs)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	if err := fileTemplate.Execute(&b, m); err != nil {
		return nil, err
	}
	return format.Source(b.Bytes())
}

// fileModel is what fileTemplate renders: every name is already resolved
// against the target package, so the template only lays code out.
type fileModel struct {
	Source  string // base name of operators.yaml
	Package string // target package name, also the prefix of error messages

	StdImports, Imports []string // import lines, each group sorted by path

	Receivers string // name of the receivers struct
	Func      string // name of the generated function
	Param     string // its parameter
	Graph     string // local name of the graph package
	Errors    string // local name of the errors package, if needed
	Errs      string // local variable collecting nil receivers

	Fields                         []receiverField
	Entries, Operators, Middleware []string // list items of the returned slice
}

type receiverField struct {
	Name, Type string
	Ptr        bool   // pointer receivers are checked for nil
	Users      string // components bound to it, for the field comment
	NilError   string // quoted message reported when it is nil
}

var fileTemplate = template.Must(template.New("file").Parse(`// Code generated by graphgen from {{.Source}}. DO NOT EDIT.

package {{.Package}}

import (
{{- range .StdImports}}
	{{.}}
{{- end}}
{{range .Imports}}
	{{.}}
{{- end}}
)

// {{.Receivers}} holds the receivers of the methods declared in {{.Source}}.
type {{.Receivers}} struct {
{{- range .Fields}}
	{{.Name}} {{.Type}} // {{.Users}}
{{- end}}
}

// {{.Func}} returns the entries, operators and middleware declared in
// {{.Source}}, with methods bound to the receivers in {{.Param}}.
{{- if .Errors}} It fails if a
// receiver is nil, listing every missing one.{{end}}
func {{.Func}}({{.Param}} {{.Receivers}}) ([]{{.Graph}}.Option, error) {
{{- if .Errors}}
	var {{.Errs}} []error
{{- range .Fields}}{{if .Ptr}}
	if {{$.Param}}.{{.Name}} == nil {
		{{$.Errs}} = append({{$.Errs}}, {{$.Errors}}.New({{.NilError}}))
	}
{{- end}}{{end}}
	if len({{.Errs}}) > 0 {
		return nil, {{.Errors}}.Join({{.Errs}}...)
	}
{{- end}}
	return []{{.Graph}}.Option{
{{- if .Entries}}
		// Entries.
{{- range .Entries}}
		{{.}},
{{- end}}
{{end}}
{{- if .Operators}}
		// Operators.
{{- range .Operators}}
		{{.}},
{{- end}}
{{end}}
{{- if .Middleware}}
		// Middleware.
{{- range .Middleware}}
		{{.}},
{{- end}}
{{- end}}
	}, nil
}
`))

func newFileModel(s *spec, target *types.Package, rs []resolved) (*fileModel, error) {
	g := &generator{target: target, aliases: make(map[string]string), names: make(map[string]string), used: make(map[string]bool)}
	m := &fileModel{
		Source:    filepath.Base(s.file),
		Package:   target.Name(),
		Receivers: receiversType,
		Func:      funcName,
	}
	m.Graph = g.fresh("graph")
	g.aliases[graphPkg], g.names[graphPkg] = m.Graph, "graph"
	for _, r := range rs {
		if r.pkg != target {
			g.alias(r.pkg)
		}
	}

	byKey := make(map[string]*receiverField)
	var keys []string
	taken := make(map[string]bool)
	for _, r := range rs {
		if r.recv == nil {
			continue
		}
		key := recvKey(r)
		f, ok := byKey[key]
		if !ok {
			base := r.recv.Obj().Name()
			name := base
			for i := 2; taken[name]; i++ {
				name = fmt.Sprintf("%s%d", base, i)
			}
			taken[name] = true
			f = &receiverField{Name: name, Type: g.qualify(r.pkg, base), Ptr: r.sym.ptr}
			if f.Ptr {
				f.Type = "*" + f.Type
			}
			byKey[key] = f
			keys = append(keys, key)
		}
		if f.Users != "" {
			f.Users += ", "
		}
		f.Users += r.name
	}
	for _, k := range keys {
		f := byKey[k]
		f.NilError = fmt.Sprintf("%q", fmt.Sprintf("%s: %s.%s is nil (needed by %s)", m.Package, receiversType, f.Name, f.Users))
		m.Fields = append(m.Fields, *f)
	}
	if slices.ContainsFunc(m.Fields, func(f receiverField) bool { return f.Ptr }) {
		m.Errors = g.fresh("errors")
		m.StdImports = []string{importLine(m.Errors, "errors", "errors")}
	}
	m.Param = g.fresh("r")
	m.Errs = g.fresh("errs")

	paths := append(slices.Clone(g.order), graphPkg)
	slices.Sort(paths)
	for _, p := range paths {
		m.Imports = append(m.Imports, importLine(g.aliases[p], p, g.names[p]))
	}

	for _, r := range rs {
		expr := g.qualify(r.pkg, r.sym.name)
		if r.recv != nil {
			expr = m.Param + "." + byKey[recvKey(r)].Name + "." + r.sym.name
		}
		switch r.kind {
		case entryDecl:
			m.Entries = append(m.Entries, expr)
		case opDecl:
			m.Operators = append(m.Operators, fmt.Sprintf("%s.Op(%q, %s)", m.Graph, r.name, expr))
		case middlewareDecl:
			m.Middleware = append(m.Middleware, fmt.Sprintf("%s.Middleware(%q, %s)", m.Graph, r.name, expr))
		default:
			return nil, fmt.Errorf("internal error: declaration %s has no kind", r.sym)
		}
	}
	return m, nil
}

// importLine renders one import spec. An import is left unnamed only when
// its local name is both the package name and the last element of the path,
// as goimports does: the two may differ, and the reader should not have to
// know which one applies.
func importLine(alias, path, name string) string {
	if alias == name && alias == pathpkg.Base(path) {
		return fmt.Sprintf("%q", path)
	}
	return fmt.Sprintf("%s %q", alias, path)
}

func recvKey(r resolved) string {
	return fmt.Sprintf("%s.%s.%v", r.pkg.Path(), r.recv.Obj().Name(), r.sym.ptr)
}

type generator struct {
	target  *types.Package
	aliases map[string]string // import path -> local name
	names   map[string]string // import path -> package name
	order   []string          // import paths in first-use order, graph excluded
	used    map[string]bool   // identifiers taken in the generated function's scope
}

func (g *generator) alias(p *types.Package) {
	if _, ok := g.aliases[p.Path()]; ok {
		return
	}
	g.aliases[p.Path()], g.names[p.Path()] = g.fresh(p.Name()), p.Name()
	g.order = append(g.order, p.Path())
}

// qualify names an exported or local identifier of package p.
func (g *generator) qualify(p *types.Package, name string) string {
	if p == g.target {
		return name
	}
	return g.aliases[p.Path()] + "." + name
}

// fresh returns base, or base2, base3... so that it clashes with nothing
// in scope: earlier names, Go keywords, predeclared identifiers and the
// target package's own top-level names.
func (g *generator) fresh(base string) string {
	if base == "" {
		base = "x"
	}
	taken := func(n string) bool {
		return g.used[n] || token.IsKeyword(n) || types.Universe.Lookup(n) != nil || g.target.Scope().Lookup(n) != nil
	}
	name := base
	for i := 2; taken(name); i++ {
		name = fmt.Sprintf("%s%d", base, i)
	}
	g.used[name] = true
	return name
}
